export const getReplaceFileUrl = (
  fileId: string,
  params: ReplaceFileParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/v1/files/${fileId}/replacement?${stringifiedParams}`
    : `/api/v1/files/${fileId}/replacement`;
};

/**
 * @summary Replacement
 */
export const replaceFile = async (
  fileId: string,
  replaceFileBody: Blob,
  params: ReplaceFileParams,
  options?: Parameters<typeof customFetch>[1],
): Promise<FileResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return customFetch<FileResponse>(getReplaceFileUrl(fileId, params), {
    ...options,
    method: "POST",
    headers: {
      "Content-Type": "application/pdf",
      ...getHeaders(options?.headers),
    },
    body: replaceFileBody,
  });
};

